source.bookSourceComment:
// Error: org.mozilla.javascript.EcmaError: TypeError: Cannot read property "1" from null (<Unknown source>#49(eval)#41) in <Unknown source>#49(eval) at line number 41

/*经过测试，阅读版本最好为测试版3.240515之后,过往版本会导致字体解析出错。*/
/*‼️注:禁止上传源仓库‼️*/
//🔻下方代码勿动🔻
// 获取源变量
_getData = () => {
  try {
    data = JSON.parse(source.getVariable()); 
    v=data.url.match(/.+readtool.+\?(.+)/)[1];
    // java.log(" 当前净化版本 : " + v); 
  } catch (err) {
    data = {}; 
  }
  return data;
};
// 保存源变量
_setData = (obj) => {
  if (typeof obj == "object") {
    source.setVariable(JSON.stringify(obj)); 
  }
};
//获取净化地址
	_getUrl = () => {
   try {
   url = java.getString("tag.script@src").match(/(https?:.+readtool.+)/)[1]; 
   } catch(err) {
     url=data.url
     }
  return url;
};
//获取正文净化规则
function getAjaxText(url) {
  result = java.ajax(url);
try {
  r = result.match(/\(null,"(.+)"/)[1];
  v = r.replace(/[a-zA-Z]/g,',');
  let arr1 = String(v).split(',');
  let str2 = String.fromCharCode.apply(null, arr1);
  c = str2.replace("document.getElementById('acontentz').innerHTML;h=h","String(h)").replace("document.getElementById('acontentz').innerHTML=h;",""); 
  } catch(e) {
  //	java.log(e);
  r = result.match(/(h=h.*)5.6\(\\'7\\'\).8=h/)[1];
  c = r.replace(/0/g,"replace").replace(/1/g,"new").replace(/2/g,"RegExp").replace(/3/g,"gi").replace(/\\/g,"").replace(/h=h/g,"h=String(h)"); 
  	}
  return c;
}
//运行
_getData();
_url = _getUrl();
if (data.url !== _url || !data.url) {
	java.log(" 获取最新url : " + _url);
	java.longToast("若正文仍不对，则说明换方法了，请前往发布页 https://yolo52.github.io/Yuedu/ 更新书源by: Yolo")
  let c = getAjaxText(_url);
  data.url = _url;
  data.c = c;
  _setData(data);
}

