source.loginJs:
function login() {
  let une = source.getLoginInfoMap().get("账号")
  let pwd = source.getLoginInfoMap().get("密码")
  if (une && pwd) {
    let body = String('username=' + une + '&password=' + pwd + '&usecookie=315360000&act=login&submit=')
    let url = 'https://www.bilinovel.com' + '/login.php'
    let ck = java.post(url, body, { "Content-Type": "application/x-www-form-urlencoded" }).cookies()
    cookie=String(ck).match(/\{(.*?)\}/)[1];
    cookie+=";night=1"
    let header = JSON.stringify({
      "Cookie": cookie
    })
    source.putLoginHeader(header)
  }
}

