<js>
t=/\[(.+_)([2-9]\b|\d{2,3})/;
m=String(result).match(t);
if(m==null){result=null;}
else{n=parseInt(m[2]);m=m[1];page=[];
for(i=2;i<n+1;i++){page[i-2]=m+String(i)+"/"};
result=page;}
</js>

